<?php
declare(strict_types=1);require_once __DIR__.'/../includes/auth.php';require_login();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$paper=$id?query_one("SELECT p.*,s.name_en,s.name_si,s.name_ta FROM practice_papers p JOIN subjects s ON s.id=p.subject_id WHERE p.id=? AND p.grade_id=? AND p.medium=? AND p.status='active'",'iis',[$id,user()['grade_id'],user()['medium']]):null;if(!$paper){flash('error','This paper is not available for your grade and medium.');redirect('student/papers.php');}$s=db()->prepare('SELECT * FROM paper_questions WHERE paper_id=? ORDER BY display_order,id');$s->bind_param('i',$id);$s->execute();$questions=$s->get_result()->fetch_all(MYSQLI_ASSOC);$pageTitle=$paper['title'];include __DIR__.'/../includes/header.php';?>
<style>.paper-head{background:linear-gradient(135deg,#172148,#344da2);color:#fff}.paper-head p{color:#d4dcff}.paper-question{overflow:visible}.paper-number{display:inline-grid;place-items:center;min-width:39px;height:39px;padding:0 10px;border-radius:13px;background:#efedff;color:var(--violet);font-weight:950}.mark-pill{float:right;padding:7px 11px;border-radius:999px;background:#fff3d7;color:#9a5d00;font-weight:900}.written-answer{min-height:130px}.model-answer summary{cursor:pointer;color:var(--violet);font-weight:900}.model-copy{padding:14px;margin-top:10px;border-radius:14px;background:#effbf7;white-space:pre-line}.paper-toolbar{display:flex;gap:10px;flex-wrap:wrap}.paper-total{font-size:1.3rem;font-weight:950}@media print{.top,.bottom,.paper-toolbar,.model-answer{display:none!important}.wrap{width:100%;padding:0}.card{box-shadow:none;border:1px solid #ddd;break-inside:avoid}}
</style><p><a href="papers.php?subject_id=<?=$paper['subject_id']?>">← Paper Practice</a></p><section class="card paper-head"><span class="badge"><?=e(locale_value($paper,'name'))?></span><h1><?=e($paper['title'])?></h1><p class="paper-total"><?=intval($paper['total_marks'])?> marks<?php if($paper['duration_minutes']):?> · <?=intval($paper['duration_minutes'])?> minutes<?php endif;?> · <?=count($questions)?> questions</p><div class="paper-toolbar"><button type="button" onclick="window.print()">🖨️ Print paper</button><button class="btn alt" type="button" id="clearAnswers">Clear my answers</button></div></section><form id="paperForm"><?php foreach($questions as $i=>$q):?><article class="card paper-question"><span class="paper-number"><?=e($q['question_number']?:$i+1)?></span><span class="mark-pill"><?=e(rtrim(rtrim((string)$q['marks'],'0'),'.'))?> marks</span><div class="study-text" style="margin:15px 0"><?=e($q['question_text'])?></div><label>Your answer<textarea class="written-answer" data-paper-answer="<?=$q['id']?>" placeholder="Write your structured answer here..."></textarea></label><details class="model-answer"><summary>Check model answer and marking guide</summary><div class="model-copy"><?=e($q['answer_text'])?></div></details></article><?php endforeach;?></form><script>const key='kedu-paper-<?=$id?>-';document.querySelectorAll('[data-paper-answer]').forEach(x=>{x.value=localStorage.getItem(key+x.dataset.paperAnswer)||'';x.addEventListener('input',()=>localStorage.setItem(key+x.dataset.paperAnswer,x.value))});document.getElementById('clearAnswers').onclick=()=>{if(confirm('Clear all your saved answers for this paper?')){document.querySelectorAll('[data-paper-answer]').forEach(x=>{x.value='';localStorage.removeItem(key+x.dataset.paperAnswer)})}}</script><?php include __DIR__.'/../includes/footer.php';
